'use client'

import { useEffect, useState } from 'react'
import {
  ArrowLeft,
  ArrowRight,
  Bell,
  CalendarDays,
  Check,
  CheckCircle2,
  ChevronDown,
  Circle,
  Flame,
  LayoutDashboard,
  ListChecks,
  Menu,
  MoreHorizontal,
  Plus,
  Search,
  Settings2,
  Sparkles,
  Target,
  X,
} from 'lucide-react'

type Habit = { id: number; name: string; icon: string; color: string; streak: number; done: boolean }
type KanbanTask = { id: number; title: string; tag: string; priority: 'High' | 'Medium' | 'Low'; column: string }
type EventItem = { id: number; title: string; date: string; time: string; color: string }

const initialHabits: Habit[] = [
  { id: 1, name: 'Morning meditation', icon: '◌', color: 'mint', streak: 12, done: true },
  { id: 2, name: 'Read 20 pages', icon: '▤', color: 'violet', streak: 8, done: false },
  { id: 3, name: 'Drink 8 glasses of water', icon: '◒', color: 'blue', streak: 5, done: false },
  { id: 4, name: 'Evening journal', icon: '✎', color: 'orange', streak: 21, done: false },
]

const initialTasks: KanbanTask[] = [
  { id: 1, title: 'Plan next week', tag: 'Personal', priority: 'High', column: 'To do' },
  { id: 2, title: 'Book dentist appointment', tag: 'Health', priority: 'Medium', column: 'To do' },
  { id: 3, title: 'Update portfolio', tag: 'Work', priority: 'High', column: 'In progress' },
  { id: 4, title: 'Organize photo library', tag: 'Personal', priority: 'Low', column: 'In progress' },
  { id: 5, title: 'Buy groceries', tag: 'Errands', priority: 'Medium', column: 'Done' },
]

const defaultEvents: EventItem[] = [
  { id: 1, title: 'Team sync', date: '2024-06-18', time: '10:00 AM', color: 'violet' },
  { id: 2, title: 'Gym session', date: '2024-06-19', time: '6:30 PM', color: 'mint' },
  { id: 3, title: 'Project review', date: '2024-06-21', time: '2:00 PM', color: 'orange' },
]

const days = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const calendarDays = Array.from({ length: 35 }, (_, i) => i - 5)

function readStored<T>(key: string, fallback: T): T {
  if (typeof window === 'undefined') return fallback
  try { return JSON.parse(localStorage.getItem(key) || 'null') ?? fallback } catch { return fallback }
}

export default function Page() {
  const [habits, setHabits] = useState<Habit[]>(initialHabits)
  const [tasks, setTasks] = useState<KanbanTask[]>(initialTasks)
  const [events, setEvents] = useState<EventItem[]>(defaultEvents)
  const [activeNav, setActiveNav] = useState('Overview')
  const [month, setMonth] = useState('June 2024')
  const [showEventForm, setShowEventForm] = useState(false)
  const [newEvent, setNewEvent] = useState({ title: '', date: '2024-06-24', time: '09:00' })
  const [newTask, setNewTask] = useState('')
  const [showTaskInput, setShowTaskInput] = useState(false)

  useEffect(() => { setHabits(readStored('habit-tracker-habits', initialHabits)); setTasks(readStored('habit-tracker-tasks', initialTasks)); setEvents(readStored('habit-tracker-events', defaultEvents)) }, [])
  useEffect(() => { localStorage.setItem('habit-tracker-habits', JSON.stringify(habits)) }, [habits])
  useEffect(() => { localStorage.setItem('habit-tracker-tasks', JSON.stringify(tasks)) }, [tasks])
  useEffect(() => { localStorage.setItem('habit-tracker-events', JSON.stringify(events)) }, [events])

  const completed = habits.filter((habit) => habit.done).length
  const totalStreak = habits.reduce((sum, habit) => sum + habit.streak, 0)
  const monthLabel = month === 'June 2024' ? 'June 2024' : month
  const toggleHabit = (id: number) => setHabits((current) => current.map((habit) => habit.id === id ? { ...habit, done: !habit.done, streak: habit.done ? Math.max(0, habit.streak - 1) : habit.streak + 1 } : habit))
  const addEvent = () => { if (!newEvent.title.trim()) return; setEvents((current) => [...current, { id: Date.now(), title: newEvent.title, date: newEvent.date, time: newEvent.time, color: 'blue' }]); setNewEvent({ title: '', date: '2024-06-24', time: '09:00' }); setShowEventForm(false) }
  const addTask = () => { if (!newTask.trim()) return; setTasks((current) => [...current, { id: Date.now(), title: newTask, tag: 'Personal', priority: 'Medium', column: 'To do' }]); setNewTask(''); setShowTaskInput(false) }
  const columns = ['To do', 'In progress', 'Done']

  return (
    <main className="min-h-screen bg-[#f7f8fa] text-[#18212b]">
      <div className="flex min-h-screen">
        <aside className="hidden w-[238px] shrink-0 border-r border-[#e6e9ee] bg-white px-5 py-7 lg:block">
          <div className="mb-12 flex items-center gap-2.5 px-2"><div className="flex size-8 items-center justify-center rounded-[10px] bg-[#c9f5d6] text-[#268249]"><Sparkles size={17} strokeWidth={2.5} /></div><span className="text-[17px] font-bold tracking-[-0.03em]">daymark</span></div>
          <nav className="space-y-1" aria-label="Main navigation">
            {[['Overview', LayoutDashboard], ['Calendar', CalendarDays], ['My habits', ListChecks], ['Kanban board', Target]].map(([label, Icon]) => <button key={label as string} onClick={() => setActiveNav(label as string)} className={`flex w-full items-center gap-3 rounded-[10px] px-3 py-2.5 text-left text-[13px] font-medium transition ${activeNav === label ? 'bg-[#eaf9ef] text-[#237a43]' : 'text-[#78818d] hover:bg-[#f4f6f8]'}`}><Icon size={17} /><span>{label as string}</span></button>)}
          </nav>
          <div className="my-8 h-px bg-[#edf0f2]" />
          <p className="px-3 text-[10px] font-bold uppercase tracking-[0.16em] text-[#a4acb5]">Workspace</p>
          <nav className="mt-3 space-y-1"><button className="flex w-full items-center gap-3 rounded-[10px] px-3 py-2.5 text-left text-[13px] font-medium text-[#78818d] hover:bg-[#f4f6f8]"><Settings2 size={17} /> Settings</button><button className="flex w-full items-center gap-3 rounded-[10px] px-3 py-2.5 text-left text-[13px] font-medium text-[#78818d] hover:bg-[#f4f6f8]"><Bell size={17} /> Notifications</button></nav>
          <div className="mt-auto hidden pt-24 lg:block"><div className="rounded-2xl bg-[#f4f7f5] p-4"><div className="mb-3 flex items-center justify-between"><span className="text-[11px] font-semibold text-[#65706a]">Weekly goal</span><span className="text-[11px] font-bold text-[#2c8b4d]">72%</span></div><div className="h-1.5 overflow-hidden rounded-full bg-[#dce9df]"><div className="h-full w-[72%] rounded-full bg-[#62c47d]" /></div><p className="mt-3 text-[11px] leading-4 text-[#929c96]">You're doing great. Keep your momentum.</p></div></div>
        </aside>

        <section className="min-w-0 flex-1">
          <header className="flex h-[76px] items-center justify-between border-b border-[#e6e9ee] bg-white px-5 sm:px-8"><div className="flex items-center gap-3"><button className="lg:hidden"><Menu size={21} /></button><div><p className="text-[11px] font-semibold uppercase tracking-[0.15em] text-[#a0a8b1]">Tuesday, June 18, 2024</p><h1 className="mt-1 text-[21px] font-bold tracking-[-0.04em]">Good morning, Alex <span className="text-[#7f8a94]">—</span></h1></div></div><div className="flex items-center gap-2.5"><button aria-label="Search" className="hidden rounded-lg p-2 text-[#82909a] hover:bg-[#f4f6f8] sm:block"><Search size={18} /></button><button aria-label="Notifications" className="relative rounded-lg p-2 text-[#82909a] hover:bg-[#f4f6f8]"><Bell size={18} /><span className="absolute right-1.5 top-1.5 size-1.5 rounded-full bg-[#54ba72]" /></button><div className="ml-1 flex size-8 items-center justify-center rounded-full bg-[#e9d5c6] text-[11px] font-bold text-[#744932]">AS</div></div></header>

          <div className="mx-auto max-w-[1390px] px-5 py-7 sm:px-8 lg:px-10">
            <div className="mb-7 grid grid-cols-2 gap-3 xl:grid-cols-4"><Stat icon={<CheckCircle2 size={18} />} label="Today's progress" value={`${completed}/${habits.length}`} note="habits completed" color="mint" /><Stat icon={<Flame size={18} />} label="Current streak" value={`${Math.max(...habits.map(h => h.streak))} days`} note="personal best: 21" color="orange" /><Stat icon={<Target size={18} />} label="Weekly completion" value="72%" note="↑ 8% from last week" color="violet" /><Stat icon={<CalendarDays size={18} />} label="Upcoming events" value={String(events.length)} note="next 7 days" color="blue" /></div>

            <div className="grid gap-6 xl:grid-cols-[minmax(0,1.25fr)_minmax(350px,0.75fr)]">
              <section className="rounded-2xl border border-[#e5e9ed] bg-white p-5 shadow-[0_2px_12px_rgba(29,42,53,0.025)] sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-[16px] font-bold tracking-[-0.02em]">Your daily habits</h2><p className="mt-1 text-[12px] text-[#89939c]">Small steps, consistent progress.</p></div><button onClick={() => setShowTaskInput(true)} className="flex items-center gap-1.5 rounded-lg border border-[#e1e6e9] px-3 py-2 text-[12px] font-semibold text-[#53616b] hover:bg-[#f6f8f8]"><Plus size={14} /> Add habit</button></div><div className="space-y-2.5">{habits.map((habit) => <div key={habit.id} className={`group flex items-center gap-3 rounded-xl border px-3.5 py-3 transition ${habit.done ? 'border-[#dcefe1] bg-[#f6fcf7]' : 'border-[#edf0f2] bg-white hover:border-[#dce4df]'}`}><button aria-label={`Mark ${habit.name} ${habit.done ? 'incomplete' : 'complete'}`} onClick={() => toggleHabit(habit.id)} className={`flex size-5 shrink-0 items-center justify-center rounded-full border-2 transition ${habit.done ? 'border-[#59be75] bg-[#59be75] text-white' : 'border-[#cbd3d5] text-transparent hover:border-[#59be75]'}`}><Check size={12} strokeWidth={3} /></button><div className={`flex size-8 items-center justify-center rounded-lg text-[16px] ${habit.color === 'mint' ? 'bg-[#e4f7e9] text-[#47a667]' : habit.color === 'violet' ? 'bg-[#eeeafd] text-[#8773ce]' : habit.color === 'blue' ? 'bg-[#e4f1fa] text-[#5995ba]' : 'bg-[#fff0e5] text-[#d9935c]'}`}>{habit.icon}</div><div className="min-w-0 flex-1"><p className={`truncate text-[13px] font-semibold ${habit.done ? 'text-[#62836d] line-through decoration-[#9fc9aa]' : 'text-[#33404b]'}`}>{habit.name}</p><p className="mt-0.5 text-[11px] text-[#a1aab1]">Daily · {habit.streak} day streak</p></div><div className="flex items-center gap-1 text-[11px] font-semibold text-[#b38a45]"><Flame size={14} fill="currentColor" /> {habit.streak}</div><button aria-label="More options" className="ml-1 text-[#c1c8cd] opacity-0 transition group-hover:opacity-100"><MoreHorizontal size={17} /></button></div>)}</div><div className="mt-5 flex items-center justify-between border-t border-[#f0f2f3] pt-4"><span className="text-[11px] font-medium text-[#9aa3aa]">Today's completion</span><span className="text-[12px] font-bold text-[#399259]">{Math.round(completed / habits.length * 100)}%</span></div><div className="mt-2 h-1.5 rounded-full bg-[#edf2ee]"><div className="h-full rounded-full bg-[#67c77f] transition-all" style={{ width: `${completed / habits.length * 100}%` }} /></div></section>

              <section className="rounded-2xl border border-[#e5e9ed] bg-white p-5 shadow-[0_2px_12px_rgba(29,42,53,0.025)] sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-[16px] font-bold tracking-[-0.02em]">This month</h2><p className="mt-1 text-[12px] text-[#89939c]">Keep your rhythm going.</p></div><div className="flex items-center gap-1"><button aria-label="Previous month" onClick={() => setMonth('May 2024')} className="rounded-md p-1.5 text-[#89939c] hover:bg-[#f2f5f3]"><ArrowLeft size={15} /></button><button aria-label="Next month" onClick={() => setMonth('July 2024')} className="rounded-md p-1.5 text-[#89939c] hover:bg-[#f2f5f3]"><ArrowRight size={15} /></button></div></div><div className="mb-3 flex items-center justify-between"><span className="text-[13px] font-bold">{monthLabel}</span><span className="rounded-full bg-[#edf9f0] px-2 py-1 text-[10px] font-bold text-[#43995c]">{totalStreak} total streak days</span></div><div className="grid grid-cols-7 gap-y-1 text-center">{days.map(day => <div key={day} className="pb-2 text-[10px] font-bold uppercase tracking-wide text-[#a5adb4]">{day.slice(0, 2)}</div>)}{calendarDays.map((date, index) => { const day = date <= 0 ? 27 + date : date; const current = date > 0 && date <= 30; const marked = current && [3, 4, 5, 7, 8, 10, 11, 12, 14, 17].includes(date); const today = date === 18; return <div key={index} className={`relative flex h-8 items-center justify-center text-[11px] ${!current ? 'text-[#d2d7da]' : today ? 'font-bold text-white' : 'text-[#697680]'}`}><span className={`${today ? 'flex size-7 items-center justify-center rounded-full bg-[#59bd73]' : marked ? 'flex size-7 items-center justify-center rounded-full bg-[#eff9f1] text-[#4b9f61]' : ''}`}>{day}</span>{marked && !today && <i className="absolute bottom-0.5 size-1 rounded-full bg-[#66c47c]" />}</div>})}</div><div className="mt-5 flex gap-4 border-t border-[#f0f2f3] pt-4 text-[10px] text-[#9ba4aa]"><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-[#67c77f]" /> Habit completed</span><span className="flex items-center gap-1.5"><i className="size-2 rounded-full bg-[#d9dfe1]" /> Rest day</span></div></section>
            </div>

            <div className="mt-6 grid gap-6 xl:grid-cols-[minmax(0,1.25fr)_minmax(350px,0.75fr)]">
              <section className="rounded-2xl border border-[#e5e9ed] bg-white p-5 shadow-[0_2px_12px_rgba(29,42,53,0.025)] sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-[16px] font-bold tracking-[-0.02em]">Kanban board</h2><p className="mt-1 text-[12px] text-[#89939c]">Move tasks forward, one step at a time.</p></div><button onClick={() => setShowTaskInput(true)} className="flex items-center gap-1.5 rounded-lg bg-[#24322d] px-3 py-2 text-[12px] font-semibold text-white hover:bg-[#31443a]"><Plus size={14} /> New task</button></div>{showTaskInput && <div className="mb-4 flex gap-2"><input autoFocus value={newTask} onChange={e => setNewTask(e.target.value)} onKeyDown={e => { if (e.key === 'Enter') addTask() }} placeholder="What needs doing?" className="min-w-0 flex-1 rounded-lg border border-[#dfe5e1] px-3 py-2 text-[12px] outline-none focus:border-[#65bd7b]" /><button onClick={addTask} className="rounded-lg bg-[#65bd7b] px-3 text-[12px] font-bold text-white">Add</button><button onClick={() => setShowTaskInput(false)} className="rounded-lg border px-2 text-[#82909a]"><X size={15} /></button></div>}<div className="grid gap-4 md:grid-cols-3">{columns.map(column => <div key={column} className="min-w-0"><div className="mb-3 flex items-center justify-between"><div className="flex items-center gap-2"><i className={`size-2 rounded-full ${column === 'To do' ? 'bg-[#b2bbc1]' : column === 'In progress' ? 'bg-[#e5b660]' : 'bg-[#65c37c]'}`} /><span className="text-[11px] font-bold uppercase tracking-[0.1em] text-[#7d8991]">{column}</span></div><span className="text-[10px] font-semibold text-[#b3bbc1]">{tasks.filter(t => t.column === column).length}</span></div><div className="space-y-2">{tasks.filter(t => t.column === column).map(task => <div key={task.id} className="rounded-xl border border-[#edf0f1] bg-[#fbfcfc] p-3"><div className="flex items-start justify-between gap-2"><p className="text-[12px] font-semibold leading-4 text-[#45525b]">{task.title}</p><button aria-label={`Move ${task.title}`} onClick={() => setTasks(current => current.map(t => t.id === task.id ? { ...t, column: column === 'To do' ? 'In progress' : column === 'In progress' ? 'Done' : 'To do' } : t))} className="shrink-0 text-[#c2c9ce] hover:text-[#718079]"><ChevronDown size={14} /></button></div><div className="mt-3 flex items-center justify-between"><span className="rounded bg-[#eef4f1] px-1.5 py-0.5 text-[9px] font-semibold text-[#75877c]">{task.tag}</span><span className={`text-[9px] font-bold ${task.priority === 'High' ? 'text-[#d77d69]' : task.priority === 'Medium' ? 'text-[#c3984e]' : 'text-[#8b9ba2]'}`}>{task.priority}</span></div></div>)}</div></div>)}</div></section>

              <section className="rounded-2xl border border-[#e5e9ed] bg-white p-5 shadow-[0_2px_12px_rgba(29,42,53,0.025)] sm:p-6"><div className="mb-5 flex items-center justify-between"><div><h2 className="text-[16px] font-bold tracking-[-0.02em]">Upcoming events</h2><p className="mt-1 text-[12px] text-[#89939c]">A clear view of what's ahead.</p></div><button onClick={() => setShowEventForm(!showEventForm)} className="flex items-center gap-1.5 rounded-lg border border-[#e1e6e9] px-3 py-2 text-[12px] font-semibold text-[#53616b] hover:bg-[#f6f8f8]"><Plus size={14} /> Add event</button></div>{showEventForm && <div className="mb-4 space-y-2 rounded-xl bg-[#f6f9f7] p-3"><input value={newEvent.title} onChange={e => setNewEvent({ ...newEvent, title: e.target.value })} placeholder="Event title" className="w-full rounded-lg border border-[#dfe5e1] bg-white px-3 py-2 text-[12px] outline-none focus:border-[#65bd7b]" /><div className="flex gap-2"><input type="date" value={newEvent.date} onChange={e => setNewEvent({ ...newEvent, date: e.target.value })} className="min-w-0 flex-1 rounded-lg border border-[#dfe5e1] bg-white px-2 py-2 text-[11px]" /><input type="time" value={newEvent.time} onChange={e => setNewEvent({ ...newEvent, time: e.target.value })} className="rounded-lg border border-[#dfe5e1] bg-white px-2 py-2 text-[11px]" /><button onClick={addEvent} className="rounded-lg bg-[#65bd7b] px-3 text-[12px] font-bold text-white">Save</button></div></div>}<div className="space-y-1">{events.sort((a, b) => a.date.localeCompare(b.date)).slice(0, 4).map(event => <div key={event.id} className="flex items-center gap-3 rounded-xl px-2 py-3 hover:bg-[#fafcfb]"><div className={`size-2 rounded-full ${event.color === 'violet' ? 'bg-[#9a85dc]' : event.color === 'orange' ? 'bg-[#e4a164]' : event.color === 'mint' ? 'bg-[#64c77e]' : 'bg-[#70a9ca]'}`} /><div className="min-w-0 flex-1"><p className="truncate text-[12px] font-semibold text-[#46535d]">{event.title}</p><p className="mt-1 text-[10px] text-[#a0a9ae]">{event.date} · {event.time}</p></div><CalendarDays size={15} className="text-[#c1c9cd]" /></div>)}</div><button onClick={() => setActiveNav('Calendar')} className="mt-3 w-full rounded-lg border border-dashed border-[#dfe6e1] py-2.5 text-[11px] font-semibold text-[#6ca27a] hover:bg-[#f7fbf8]">View full calendar</button></section>
            </div>
          </div>
        </section>
      </div>
    </main>
  )
}

function Stat({ icon, label, value, note, color }: { icon: React.ReactNode; label: string; value: string; note: string; color: string }) { return <div className="rounded-2xl border border-[#e5e9ed] bg-white p-4 shadow-[0_2px_12px_rgba(29,42,53,0.025)] sm:p-5"><div className="flex items-start justify-between"><div className={`flex size-8 items-center justify-center rounded-lg ${color === 'mint' ? 'bg-[#e5f8ea] text-[#4daf69]' : color === 'orange' ? 'bg-[#fff1e5] text-[#d9945a]' : color === 'violet' ? 'bg-[#eeeafd] text-[#8874ca]' : 'bg-[#e5f2fa] text-[#6099ba]'}`}>{icon}</div><MoreHorizontal size={16} className="text-[#c8ced2]" /></div><p className="mt-4 text-[11px] font-semibold text-[#89949c]">{label}</p><p className="mt-1 text-[22px] font-bold tracking-[-0.05em] text-[#26343e]">{value}</p><p className="mt-1 text-[10px] text-[#a7afb5]">{note}</p></div> }
